// ---- Build Prompt (Versuch 1) ----
const payload = ($('Webhook').first().json.body) || $('Webhook').first().json || {};
const difficulty = ["easy","medium","hard"].includes(payload.difficulty) ? payload.difficulty : "medium";

const SUBTLETY = {
  easy:   "Die Qualitaetsunterschiede zwischen den fuenf Prompts duerfen deutlich sein; die Halluzination im strong_but_trap-Output darf leicht auffallen.",
  medium: "Die schwachen Prompts sollen auf den ersten Blick brauchbar wirken; die Halluzination im strong_but_trap-Output soll plausibel klingen und erst beim Abgleich mit der Datenbasis auffallen.",
  hard:   "Alle fuenf Prompts sollen professionell klingen und sich nur in Nuancen unterscheiden; die Halluzination im strong_but_trap-Output soll sehr ueberzeugend sein und nur durch genauen Abgleich mit der Datenbasis erkennbar sein."
};
const learningGoal = payload.learningGoal === "other"
  ? (payload.learningGoalCustom || "Allgemeines Finance-Thema")
  : (payload.learningGoal || "Allgemeines Finance-Thema");
const techLabel   = payload.technologyLabel || payload.technologyCustom || "KI-Technologie";
const techContext = payload.technologyWhatsNew ? ("Kontext zur Technologie: " + payload.technologyWhatsNew) : "";

const systemPrompt = `Du bist Spiel-Generator fuer "Prompt Navigator"-Challenges der Lufthansa Finance Training Academy. Zielgruppe: eine Controllerin ohne KI-Vorwissen. Sie soll lernen: gute Prompts erkennen (CRAFT: Context, Role, Action, Format, Tone), simulierte KI-Outputs kritisch pruefen (v.a. Halluzinationen erkennen) und gezielt nachsteuern.

Gib AUSSCHLIESSLICH valides JSON zurueck, KEINE Markdown-Code-Bloecke, exakt in diesem Format:
{
 "scenario": {
   "intro": "<Situation + Aufgabe + DATENBASIS: mindestens 3 konkrete Zahlen (Betraege, Perioden, Kennzahlen). Alles, was eine KI wissen duerfte, steht ausschliesslich HIER.>",
   "personaNote": "<1 Satz Einordnung fuer die Spielerin>"
 },
 "startQuestion": "<1 Satz: welche der fuenf Prompt-Karten schickt sie ab?>",
 "prompts": [ genau 5 Objekte, jeder qualityTier genau einmal: "perfect", "strong_but_trap", "weak_no_data", "weak_no_context", "weak_vague" ],
 "lessons": [ 5 Objekte { "craftElement": "<CRAFT-Element, z.B. Context>", "text": "<Lektion, 1-2 Saetze>" } ],
 "recapIntro": "<2-3 Saetze Abschluss-Fazit>"
}

Jedes prompts-Objekt:
{
 "qualityTier": "<einer der 5 Werte>",
 "label": "<Karten-Titel, 3-6 Woerter, beschreibt den STIL des Prompts, verraet NICHT seine Qualitaet>",
 "promptText": "<der vollstaendige Prompt im Wortlaut, wie ihn die Spielerin abschicken wuerde>",
 "aiOutput": "<die simulierte KI-Antwort auf genau diesen Prompt, 60-120 Woerter>",
 "ratingLabel": "<kurzes Qualitaetsurteil>",
 "explanation": "<2-3 Saetze: warum fiel der Output so aus, mit Bezug auf den Prompt>",
 "diagnosis": { "question": "<Was war das Kernproblem dieses Prompts?>", "options": [ genau 3 Objekte { "text": "...", "isCorrect": true|false, "feedback": "<Lernfeedback>" } ] },
 "correction": { "question": "<Wie steuerst du jetzt nach?>", "good": { "label": "...", "promptText": "...", "aiOutput": "...", "ratingLabel": "...", "explanation": "..." }, "meh": { "label": "...", "promptText": "...", "aiOutput": "...", "ratingLabel": "...", "explanation": "..." } }
}
Beim qualityTier "perfect" entfallen "diagnosis" und "correction" komplett (Felder weglassen).

HARTE REGELN:
- Tier-Semantik: "perfect" = CRAFT-vollstaendiger Prompt MIT Anti-Halluzinations-Klausel (z.B. "nutze ausschliesslich die genannten Zahlen, erfinde nichts"); sein aiOutput nutzt NUR Zahlen aus der Datenbasis und ist fehlerfrei. "strong_but_trap" = fast identisch guter Prompt, aber OHNE Anti-Halluzinations-Klausel; sein aiOutput ist stark, enthaelt aber GENAU EINE plausible erfundene Behauptung oder Zahl, die NICHT in der Datenbasis steht (die Halluzination). "weak_no_data" = Prompt uebergibt die Datenbasis nicht; sein aiOutput erfindet durchgehend plausible Zahlen. "weak_no_context" = Prompt ohne Geschaeftskontext und Rolle; sein aiOutput ist generisch und geht am Ziel vorbei. "weak_vague" = vager Einzeiler; sein aiOutput ist pauschal und ohne Zahlen.
- In diagnosis hat GENAU EINE Option isCorrect true. Die korrekte Diagnose-Option bei strong_but_trap MUSS die erfundene Behauptung konkret benennen. Distraktoren klingen plausibel; feedback erklaert, warum richtig bzw. falsch.
- correction.good behebt exakt den Kerndefekt des jeweiligen Prompts (fehlende Daten nachliefern, Kontext ergaenzen, Halluzination adressieren); sein aiOutput ist stark und NUR datenbasiert; sein ratingLabel enthaelt das Wort "Ausgezeichnet". correction.meh ist eine vage Nachbesserung; sein aiOutput bleibt schwach.
- perfect.ratingLabel enthaelt "Ausgezeichnet" oder "Perfekt".
- Die aiOutputs von perfect, strong_but_trap und allen correction.good enthalten konkrete Zahlen.
- Alle 5 promptText beziehen sich auf DIESELBE Aufgabe aus scenario.intro.
- Alle Texte auf Deutsch. Antworte nur mit dem JSON-Objekt.
- ${SUBTLETY[difficulty]}

Schwierigkeit: ${difficulty}. Lernziel: ${learningGoal}. Technologie-Bezug: ${techLabel}. ${techContext}`;

const userPrompt = `Erzeuge jetzt eine Prompt-Navigator-Challenge zum Lernziel "${learningGoal}" mit Bezug zur Technologie "${techLabel}", Schwierigkeit "${difficulty}". Gib ausschliesslich das JSON im vorgegebenen Format zurueck.`;

const llm_body = {
  model: "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [{ role:"system", content: systemPrompt }, { role:"user", content: userPrompt }],
  temperature: 0.7,
  max_tokens: 8000
};
return [{ json: { llm_body, attempt: 1, difficulty, payload } }];

// ---- Process & Validate (Versuch 1) ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const attempt = 1;

const TIERS = ["perfect","strong_but_trap","weak_no_data","weak_no_context","weak_vague"];
const nonEmpty = (x) => x != null && String(x).trim().length > 0;
const T = (x) => String(x).trim();

function fail(errors, raw){ return [{ json:{ valid:false, errors, data:null, payload,
  meta:{ attempt, model: bp.llm_body.model }, raw } }]; }

let content = "";
try { content = resp.choices[0].message.content; }
catch(e){ return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cleaned.indexOf("{"), e = cleaned.lastIndexOf("}");
  data = JSON.parse(s!==-1 && e!==-1 ? cleaned.slice(s,e+1) : cleaned);
} catch(e){ return fail(["LLM-Ausgabe ist kein valides JSON (evtl. abgeschnitten -> max_tokens): " + e.message], content); }

const errors = [];

const sc = data.scenario || {};
if (!nonEmpty(sc.intro)) errors.push("scenario.intro leer");
else if (!/\d/.test(String(sc.intro))) errors.push("scenario.intro ohne konkrete Zahl (keine Datenbasis)");
if (!nonEmpty(data.startQuestion)) errors.push("startQuestion leer");

const prompts = Array.isArray(data.prompts) ? data.prompts : [];
if (prompts.length !== 5) errors.push("prompts: erwartet 5, erhalten " + prompts.length);

const seen = {};
prompts.forEach((pr,i)=>{
  const n = "Prompt " + (i+1) + ": ";
  if (!pr || typeof pr !== "object"){ errors.push(n + "kein Objekt"); return; }
  if (!TIERS.includes(pr.qualityTier)) errors.push(n + "qualityTier ungueltig: " + JSON.stringify(pr.qualityTier));
  else { if (seen[pr.qualityTier]) errors.push(n + "qualityTier doppelt: " + pr.qualityTier); seen[pr.qualityTier] = true; }

  ["label","promptText","aiOutput","ratingLabel","explanation"].forEach(f=>{
    if (!nonEmpty(pr[f])) errors.push(n + f + " leer");
  });
  if ((pr.qualityTier === "perfect" || pr.qualityTier === "strong_but_trap") && nonEmpty(pr.aiOutput) && !/\d/.test(String(pr.aiOutput)))
    errors.push(n + "aiOutput (" + pr.qualityTier + ") ohne konkrete Zahl");

  if (pr.qualityTier && pr.qualityTier !== "perfect") {
    const dg = pr.diagnosis || {};
    if (!nonEmpty(dg.question)) errors.push(n + "diagnosis.question leer");
    const dOpts = Array.isArray(dg.options) ? dg.options : [];
    if (dOpts.length < 2 || dOpts.length > 4) errors.push(n + "diagnosis.options: erwartet 2-4, erhalten " + dOpts.length);
    let correct = 0;
    dOpts.forEach((o,j)=>{
      if (!nonEmpty((o||{}).text)) errors.push(n + "diagnosis.options[" + (j+1) + "].text leer");
      if (!nonEmpty((o||{}).feedback)) errors.push(n + "diagnosis.options[" + (j+1) + "].feedback leer");
      if ((o||{}).isCorrect === true) correct++;
    });
    if (dOpts.length && correct !== 1) errors.push(n + "diagnosis: genau 1 Option mit isCorrect=true erwartet, erhalten " + correct);

    const co = pr.correction || {};
    if (!nonEmpty(co.question)) errors.push(n + "correction.question leer");
    ["good","meh"].forEach(k=>{
      const c = co[k] || {};
      ["label","promptText","aiOutput","ratingLabel","explanation"].forEach(f=>{
        if (!nonEmpty(c[f])) errors.push(n + "correction." + k + "." + f + " leer");
      });
    });
    const g = (co.good||{}).aiOutput, m = (co.meh||{}).aiOutput;
    if (nonEmpty(g) && nonEmpty(m) && T(g) === T(m)) errors.push(n + "correction: good.aiOutput und meh.aiOutput identisch");
    if (nonEmpty(g) && !/\d/.test(String(g))) errors.push(n + "correction.good.aiOutput ohne konkrete Zahl");
  }
});
if (prompts.length === 5) TIERS.forEach(t=>{ if (!seen[t]) errors.push("qualityTier fehlt: " + t); });

const lessons = Array.isArray(data.lessons) ? data.lessons : [];
if (lessons.length < 3) errors.push("lessons: mindestens 3 erwartet, erhalten " + lessons.length);
lessons.forEach((l,i)=>{
  if (!nonEmpty((l||{}).craftElement)) errors.push("lessons[" + (i+1) + "].craftElement leer");
  if (!nonEmpty((l||{}).text)) errors.push("lessons[" + (i+1) + "].text leer");
});
if (!nonEmpty(data.recapIntro)) errors.push("recapIntro leer");

if (errors.length) return fail(errors, content);

// ---- Clean copy (getrimmt, nur erwartete Felder) ----
const clean = {
  scenario: Object.assign({ intro: T(sc.intro) }, nonEmpty(sc.personaNote) ? { personaNote: T(sc.personaNote) } : {}),
  startQuestion: T(data.startQuestion),
  prompts: prompts.map(pr => {
    const base = {
      qualityTier: pr.qualityTier, label: T(pr.label), promptText: T(pr.promptText),
      aiOutput: T(pr.aiOutput), ratingLabel: T(pr.ratingLabel), explanation: T(pr.explanation)
    };
    if (pr.qualityTier !== "perfect") {
      base.diagnosis = {
        question: T(pr.diagnosis.question),
        options: pr.diagnosis.options.map(o => ({ text: T(o.text), isCorrect: o.isCorrect === true, feedback: T(o.feedback) }))
      };
      const mk = (c) => ({ label: T(c.label), promptText: T(c.promptText), aiOutput: T(c.aiOutput), ratingLabel: T(c.ratingLabel), explanation: T(c.explanation) });
      base.correction = { question: T(pr.correction.question), good: mk(pr.correction.good), meh: mk(pr.correction.meh) };
    }
    return base;
  }),
  lessons: lessons.map(l => ({ craftElement: T(l.craftElement), text: T(l.text) })),
  recapIntro: T(data.recapIntro)
};

return [{ json: { valid:true, errors:[], data: clean, payload,
  meta:{ attempt, model: bp.llm_body.model, tokens: usage }, raw:null } }];

// ---- Build Repair Prompt (Versuch 2) ----
const prev = $('Process & Validate 1').first().json;
const bp = $('Build Prompt').first().json;
const errors = prev.errors || [];

const repairSystem = bp.llm_body.messages[0].content;
const repairUser = "Dein vorheriger Versuch war UNGUELTIG. Zu behebende Fehler:\n- "
  + errors.join("\n- ")
  + "\n\nDein vorheriger (fehlerhafter) Output:\n" + JSON.stringify(prev.raw)
  + "\n\nKorrigiere GENAU diese Fehler und gib erneut AUSSCHLIESSLICH das valide JSON im vorgegebenen Format zurueck.";

const llm_body = {
  model: bp.llm_body.model,
  messages: [{ role:"system", content: repairSystem }, { role:"user", content: repairUser }],
  temperature: 0.2,
  max_tokens: 8000
};
return [{ json: { llm_body, attempt:2, difficulty: bp.difficulty, payload: bp.payload } }];

// ---- Process & Validate (Versuch 2) ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const attempt = 2;

const TIERS = ["perfect","strong_but_trap","weak_no_data","weak_no_context","weak_vague"];
const nonEmpty = (x) => x != null && String(x).trim().length > 0;
const T = (x) => String(x).trim();

function fail(errors, raw){ return [{ json:{ valid:false, errors, data:null, payload,
  meta:{ attempt, model: bp.llm_body.model }, raw } }]; }

let content = "";
try { content = resp.choices[0].message.content; }
catch(e){ return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cleaned.indexOf("{"), e = cleaned.lastIndexOf("}");
  data = JSON.parse(s!==-1 && e!==-1 ? cleaned.slice(s,e+1) : cleaned);
} catch(e){ return fail(["LLM-Ausgabe ist kein valides JSON (evtl. abgeschnitten -> max_tokens): " + e.message], content); }

const errors = [];

const sc = data.scenario || {};
if (!nonEmpty(sc.intro)) errors.push("scenario.intro leer");
else if (!/\d/.test(String(sc.intro))) errors.push("scenario.intro ohne konkrete Zahl (keine Datenbasis)");
if (!nonEmpty(data.startQuestion)) errors.push("startQuestion leer");

const prompts = Array.isArray(data.prompts) ? data.prompts : [];
if (prompts.length !== 5) errors.push("prompts: erwartet 5, erhalten " + prompts.length);

const seen = {};
prompts.forEach((pr,i)=>{
  const n = "Prompt " + (i+1) + ": ";
  if (!pr || typeof pr !== "object"){ errors.push(n + "kein Objekt"); return; }
  if (!TIERS.includes(pr.qualityTier)) errors.push(n + "qualityTier ungueltig: " + JSON.stringify(pr.qualityTier));
  else { if (seen[pr.qualityTier]) errors.push(n + "qualityTier doppelt: " + pr.qualityTier); seen[pr.qualityTier] = true; }

  ["label","promptText","aiOutput","ratingLabel","explanation"].forEach(f=>{
    if (!nonEmpty(pr[f])) errors.push(n + f + " leer");
  });
  if ((pr.qualityTier === "perfect" || pr.qualityTier === "strong_but_trap") && nonEmpty(pr.aiOutput) && !/\d/.test(String(pr.aiOutput)))
    errors.push(n + "aiOutput (" + pr.qualityTier + ") ohne konkrete Zahl");

  if (pr.qualityTier && pr.qualityTier !== "perfect") {
    const dg = pr.diagnosis || {};
    if (!nonEmpty(dg.question)) errors.push(n + "diagnosis.question leer");
    const dOpts = Array.isArray(dg.options) ? dg.options : [];
    if (dOpts.length < 2 || dOpts.length > 4) errors.push(n + "diagnosis.options: erwartet 2-4, erhalten " + dOpts.length);
    let correct = 0;
    dOpts.forEach((o,j)=>{
      if (!nonEmpty((o||{}).text)) errors.push(n + "diagnosis.options[" + (j+1) + "].text leer");
      if (!nonEmpty((o||{}).feedback)) errors.push(n + "diagnosis.options[" + (j+1) + "].feedback leer");
      if ((o||{}).isCorrect === true) correct++;
    });
    if (dOpts.length && correct !== 1) errors.push(n + "diagnosis: genau 1 Option mit isCorrect=true erwartet, erhalten " + correct);

    const co = pr.correction || {};
    if (!nonEmpty(co.question)) errors.push(n + "correction.question leer");
    ["good","meh"].forEach(k=>{
      const c = co[k] || {};
      ["label","promptText","aiOutput","ratingLabel","explanation"].forEach(f=>{
        if (!nonEmpty(c[f])) errors.push(n + "correction." + k + "." + f + " leer");
      });
    });
    const g = (co.good||{}).aiOutput, m = (co.meh||{}).aiOutput;
    if (nonEmpty(g) && nonEmpty(m) && T(g) === T(m)) errors.push(n + "correction: good.aiOutput und meh.aiOutput identisch");
    if (nonEmpty(g) && !/\d/.test(String(g))) errors.push(n + "correction.good.aiOutput ohne konkrete Zahl");
  }
});
if (prompts.length === 5) TIERS.forEach(t=>{ if (!seen[t]) errors.push("qualityTier fehlt: " + t); });

const lessons = Array.isArray(data.lessons) ? data.lessons : [];
if (lessons.length < 3) errors.push("lessons: mindestens 3 erwartet, erhalten " + lessons.length);
lessons.forEach((l,i)=>{
  if (!nonEmpty((l||{}).craftElement)) errors.push("lessons[" + (i+1) + "].craftElement leer");
  if (!nonEmpty((l||{}).text)) errors.push("lessons[" + (i+1) + "].text leer");
});
if (!nonEmpty(data.recapIntro)) errors.push("recapIntro leer");

if (errors.length) return fail(errors, content);

// ---- Clean copy (getrimmt, nur erwartete Felder) ----
const clean = {
  scenario: Object.assign({ intro: T(sc.intro) }, nonEmpty(sc.personaNote) ? { personaNote: T(sc.personaNote) } : {}),
  startQuestion: T(data.startQuestion),
  prompts: prompts.map(pr => {
    const base = {
      qualityTier: pr.qualityTier, label: T(pr.label), promptText: T(pr.promptText),
      aiOutput: T(pr.aiOutput), ratingLabel: T(pr.ratingLabel), explanation: T(pr.explanation)
    };
    if (pr.qualityTier !== "perfect") {
      base.diagnosis = {
        question: T(pr.diagnosis.question),
        options: pr.diagnosis.options.map(o => ({ text: T(o.text), isCorrect: o.isCorrect === true, feedback: T(o.feedback) }))
      };
      const mk = (c) => ({ label: T(c.label), promptText: T(c.promptText), aiOutput: T(c.aiOutput), ratingLabel: T(c.ratingLabel), explanation: T(c.explanation) });
      base.correction = { question: T(pr.correction.question), good: mk(pr.correction.good), meh: mk(pr.correction.meh) };
    }
    return base;
  }),
  lessons: lessons.map(l => ({ craftElement: T(l.craftElement), text: T(l.text) })),
  recapIntro: T(data.recapIntro)
};

return [{ json: { valid:true, errors:[], data: clean, payload,
  meta:{ attempt, model: bp.llm_body.model, tokens: usage }, raw:null } }];

// ---- Build Blind Prompt (Faktencheck, Generierungs-Zeit) ----
const v = $json;                 // valide PV-Ausgabe (aus PV1 ODER PV2)
const d = v.data;
const perfect = d.prompts.find(p => p.qualityTier === "perfect");
const trap    = d.prompts.find(p => p.qualityTier === "strong_but_trap");

// Judge sieht nicht, welcher Output der Trap ist -> zufaellig A/B
const trapIsA = Math.random() < 0.5;
const A = trapIsA ? trap.aiOutput : perfect.aiOutput;
const B = trapIsA ? perfect.aiOutput : trap.aiOutput;
const trapLabel = trapIsA ? "A" : "B";   // NUR fuer den Code, NICHT im Prompt

const system = `Du bist ein strenger Finance-Fakten-Pruefer. Du erhaeltst eine DATENBASIS und zwei KI-Antworten (A und B) auf dieselbe Aufgabe. Pruefe fuer JEDE Antwort einzeln und unabhaengig: Enthaelt sie mindestens eine konkrete Behauptung oder Zahl, die NICHT durch die Datenbasis gedeckt ist? Antworte AUSSCHLIESSLICH mit JSON: {"A":{"unsupportedClaim":true},"B":{"unsupportedClaim":false}}`;
const user = `DATENBASIS:\n${d.scenario.intro}\n\nAntwort A:\n${A}\n\nAntwort B:\n${B}`;

const llm_body = {
  model: v.meta.model || "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [{ role:"system", content: system }, { role:"user", content: user }],
  temperature: 0,
  max_tokens: 200
};
return [{ json: { llm_body, trapLabel, carry: v } }];

// ---- Process Blind + Assemble DB Row (deterministische Graph-Assembly) ----
const resp = $json;
const bb = $('Build Blind Prompt').first().json;
const v = bb.carry;
const d = v.data;
const p = v.payload || {};

// --- Blind-Verdikt parsen (fail-soft: darf NIE den Insert blockieren) ---
let blindPassed = null;            // null = nicht durchfuehrbar -> Curator entscheidet
const disagreements = [];
try {
  const c = resp.choices[0].message.content;
  const cl = String(c).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cl.indexOf("{"), e = cl.lastIndexOf("}");
  const parsed = JSON.parse(s!==-1 && e!==-1 ? cl.slice(s,e+1) : cl);
  const perfLabel = bb.trapLabel === "A" ? "B" : "A";
  const trapV = parsed[bb.trapLabel], perfV = parsed[perfLabel];
  if (trapV && perfV && typeof trapV.unsupportedClaim === "boolean" && typeof perfV.unsupportedClaim === "boolean") {
    if (trapV.unsupportedClaim !== true)  disagreements.push("trap_output_ohne_erkennbare_halluzination");
    if (perfV.unsupportedClaim !== false) disagreements.push("perfect_output_mit_ungestuetzter_behauptung");
    blindPassed = disagreements.length === 0;
  }
} catch(e) { blindPassed = null; }

// --- Punkte: deterministisch aus qualityTier (LLM erfindet, Code rechnet) ---
const TIER_POINTS = { perfect: 6, strong_but_trap: 2, weak_no_data: 0, weak_no_context: 0, weak_vague: 0 };
const DIAG_POINTS = 2, FIX_POINTS = 2;

// perfect deterministisch auf Index 3 (= Option 'prompt_d') -> Player-Badge-Kopplung
const arranged = d.prompts.slice();
const pi = arranged.findIndex(x => x.qualityTier === "perfect");
if (pi !== 3) { const tmp = arranged[3]; arranged[3] = arranged[pi]; arranged[pi] = tmp; }

const letters = ["a","b","c","d","e"];
// Celebration-Kopplung im Player: ratingLabel muss 'Ausgezeichnet'/'Perfekt' enthalten
const forceExcellent = (lbl) => /ausgezeichnet|perfekt/i.test(lbl) ? lbl : "Ausgezeichnet";

const nodes = {};
nodes["start"] = {
  type: "prompt_choice",
  text: d.startQuestion,
  options: arranged.map((pr,i) => ({
    id: "prompt_" + letters[i], label: pr.label, promptText: pr.promptText,
    points: TIER_POINTS[pr.qualityTier], nextNode: letters[i] + "_result"
  }))
};

arranged.forEach((pr,i) => {
  const x = letters[i];
  const isPerfect = pr.qualityTier === "perfect";

  nodes[x + "_result"] = {
    type: "output_review",
    aiOutput: pr.aiOutput,
    ratingLabel: isPerfect ? forceExcellent(pr.ratingLabel) : pr.ratingLabel,
    explanation: pr.explanation,
    nextNode: isPerfect ? "end_recap" : x + "_diagnosis"
  };
  if (isPerfect) return;

  nodes[x + "_diagnosis"] = {
    type: "diagnosis",
    text: pr.diagnosis.question,
    options: pr.diagnosis.options.map((o,j) => ({
      id: x + "_diag_" + (j+1), label: o.text,
      points: o.isCorrect ? DIAG_POINTS : 0, feedback: o.feedback,
      nextNode: x + "_correction"
    }))
  };

  const goodOpt = { id: x + "_fix_good", label: pr.correction.good.label, promptText: pr.correction.good.promptText,
    points: FIX_POINTS, nextNode: x + "_correction_result_good" };
  const mehOpt  = { id: x + "_fix_meh",  label: pr.correction.meh.label,  promptText: pr.correction.meh.promptText,
    points: 0, nextNode: x + "_correction_result_meh" };
  nodes[x + "_correction"] = {
    type: "prompt_choice",
    text: pr.correction.question,
    options: Math.random() < 0.5 ? [goodOpt, mehOpt] : [mehOpt, goodOpt]   // good nicht immer zuerst
  };

  nodes[x + "_correction_result_good"] = {
    type: "output_review", aiOutput: pr.correction.good.aiOutput,
    ratingLabel: forceExcellent(pr.correction.good.ratingLabel),
    explanation: pr.correction.good.explanation, nextNode: "end_recap"
  };
  nodes[x + "_correction_result_meh"] = {
    type: "output_review", aiOutput: pr.correction.meh.aiOutput,
    ratingLabel: pr.correction.meh.ratingLabel,
    explanation: pr.correction.meh.explanation, nextNode: "end_recap"
  };
});

nodes["end_recap"] = { type: "end", recapIntro: d.recapIntro, lessons: d.lessons };

// --- Scoring deterministisch aus der Pfadstruktur ---
// bester Spielverlauf je Ast: Erstwahl + (falls nicht perfect) korrekte Diagnose + gute Korrektur
const pathTotals = arranged.map(pr => pr.qualityTier === "perfect"
  ? TIER_POINTS.perfect
  : TIER_POINTS[pr.qualityTier] + DIAG_POINTS + FIX_POINTS);
const maxPoints = Math.max.apply(null, pathTotals);      // global bester Pfad
const passingScore = Math.min.apply(null, pathTotals);   // schwaechster Start + volle Recovery besteht noch

// --- Struktur-Assertions (muessen per Konstruktion halten; werfen = Bug im Assemble) ---
Object.keys(nodes).forEach(k => {
  const nd = nodes[k];
  const targets = [];
  if (nd.nextNode) targets.push(nd.nextNode);
  (nd.options || []).forEach(o => { if (o.nextNode) targets.push(o.nextNode); else throw new Error("Option ohne nextNode in " + k); });
  targets.forEach(t => { if (!nodes[t]) throw new Error("Dangling Edge: " + k + " -> " + t); });
});
if (!nodes["start"]) throw new Error("startNode fehlt");
if (maxPoints <= 0 || passingScore > maxPoints) throw new Error("Scoring inkonsistent");

const game_json = {
  format: "prompt_branching",
  branching: {
    scenario: d.scenario,
    startNode: "start",
    nodes,
    scoring: { maxPoints, passingScore }
  }
};

// Blind-Ergebnis aendert NICHT den Status - lebt nur in generation_meta.blindCheck.
const status = "draft";

const techLabel = p.technologyLabel || p.technologyCustom || "KI";
const goalLabel = p.learningGoal === "other" ? (p.learningGoalCustom || "Finance") : (p.learningGoal || "Finance");
const goalDisplay = p.learningGoal === "other" ? (p.learningGoalCustom || null) : (p.learningGoal || null);

return [{ json: {
  title: `Prompt Navigator: ${goalLabel} \u2013 ${techLabel}`,
  format: p.gameType || "prompt_branching",
  difficulty: p.difficulty || "medium",
  language: "de",
  learning_objective: goalDisplay,
  game_json,
  status,
  technology_id: (p.technologyId && p.technologyId !== "other") ? p.technologyId : null,
  technology_custom: p.technologyId === "other" ? (p.technologyCustom || null) : null,
  learning_goal: p.learningGoal !== "other" ? p.learningGoal : null,
  learning_goal_custom: p.learningGoal === "other" ? (p.learningGoalCustom || null) : null,
  requested_by: p.requestedBy || null,
  generation_meta: Object.assign({}, v.meta || {}, { blindCheck: { passed: blindPassed, disagreements } }),
  created_at: new Date().toISOString()
}}];
